import { Spinner } from '@/components/ui/spinner';
import { Table } from '@/components/ui/table';
import { formatDate } from '@/utils/format';
import { User } from '@/types/api';

import { useUsers } from '../api/get-users';
import { useUpdateUserRole } from '../api/update-user-role';

import { DeleteUser } from './delete-user';

// Helper component for the role select
const UserRoleSelect = ({
  userId,
  currentRole,
}: {
  userId: string;
  currentRole: 'ADMIN' | 'USER';
}) => {
  const { mutate, isLoading } = useUpdateUserRole();

  const handleChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    mutate({
      userId,
      newRole: e.target.value as 'ADMIN' | 'USER',
    });
  };

  return (
    <select
      value={currentRole}
      onChange={handleChange}
      disabled={isLoading}
      className="block w-full rounded-md border-gray-300 py-1 pl-2 pr-8 text-sm focus:border-blue-500 focus:ring-blue-500"
    >
      <option value="ADMIN">ADMIN</option>
      <option value="USER">USER</option>
    </select>
  );
};

export const UsersList = () => {
  const usersQuery = useUsers();

  if (usersQuery.isLoading) {
    return (
      <div className="flex h-48 w-full items-center justify-center">
        <Spinner size="lg" />
      </div>
    );
  }

  const users = usersQuery.data?.data;

  if (!users) return null;

  return (
    <Table
      data={users}
      columns={[
        {
          title: 'First Name',
          field: 'firstName',
        },
        {
          title: 'Last Name',
          field: 'lastName',
        },
        {
          title: 'Email',
          field: 'email',
        },
        {
          title: 'Role',
          field: 'role',
          Cell({ entry }: { entry: User }) {
            return <UserRoleSelect userId={entry.id} currentRole={entry.role} />;
          },
        },
        {
          title: 'Created At',
          field: 'createdAt',
          Cell({ entry: { createdAt } }) {
            return <span>{formatDate(createdAt)}</span>;
          },
        },
        {
          title: '',
          field: 'id',
          Cell({ entry: { id } }) {
            return <DeleteUser id={id} />;
          },
        },
      ]}
    />
  );
};

